mapper.select:
SELECT id AS image_id, object_key, thumbnail_object_key AS thumbnail_key
FROM memory_image
WHERE memory_id IS NULL
  AND created_at < #{createdBefore}
ORDER BY id
LIMIT #{limit}

SELECT id AS image_id, object_key, thumbnail_object_key AS thumbnail_key
FROM memory_image
WHERE member_id = #{memberId}
  AND memory_id IS NULL
  AND id > #{afterId}
ORDER BY id
LIMIT #{limit}

mapper.delete:
DELETE FROM memory_image
WHERE id = #{imageId}
  AND memory_id IS NULL

mapper.select:
SELECT created_at
FROM memory_image
WHERE member_id = #{memberId}
  AND memory_id IS NULL
  AND created_at > #{createdAfter}
ORDER BY created_at
LIMIT #{limit}
